package com.onebytelabs.zlplay;
import android.graphics.*;import android.graphics.drawable.Drawable;import android.os.Handler;import android.view.*;import android.widget.*;import java.util.*;import java.util.function.*;
/** In-window hold/drag reorder. Avoids transferring touch ownership to Android's system drag window. */
public final class ReorderController {
 private final ScrollView scroll;private final Handler handler;private final BooleanSupplier enabled;private final BiConsumer<Integer,Integer> commit;private final List<View> rows=new ArrayList<>();private final int[] location=new int[2];private final Marker marker=new Marker();private View source,marked;private int from,insertion;private float rawY;private boolean bottom;private final float density;
 public ReorderController(ScrollView scroll,Handler handler,BooleanSupplier enabled,BiConsumer<Integer,Integer> commit){this.scroll=scroll;this.handler=handler;this.enabled=enabled;this.commit=commit;density=scroll.getResources().getDisplayMetrics().density;}
 public void attach(View row){final int index=rows.size();rows.add(row);row.setOnTouchListener((v,event)->{if(event.getActionMasked()==MotionEvent.ACTION_DOWN)rawY=event.getRawY();if(source!=v)return false;rawY=event.getRawY();if(event.getActionMasked()==MotionEvent.ACTION_MOVE){update();return true;}if(event.getActionMasked()==MotionEvent.ACTION_UP){update();int start=from,target=insertion;cancel();commit.accept(start,target);return true;}if(event.getActionMasked()==MotionEvent.ACTION_CANCEL){cancel();return true;}return true;});row.setOnLongClickListener(v->{if(!enabled.getAsBoolean())return false;source=v;from=index;insertion=index;v.setPressed(false);v.setAlpha(.55f);v.getParent().requestDisallowInterceptTouchEvent(true);v.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS);update();handler.post(ticker);return true;});}
 private final Runnable ticker=new Runnable(){public void run(){if(source==null)return;scroll.getLocationOnScreen(location);float y=rawY-location[1],edge=45*density;int delta=y<edge?-(int)(7*density):y>scroll.getHeight()-edge?(int)(7*density):0;if(delta!=0){scroll.scrollBy(0,delta);update();}handler.postDelayed(this,16);}};
 private void update(){insertion=rows.size();for(int i=0;i<rows.size();i++){View row=rows.get(i);row.getLocationOnScreen(location);if(rawY<location[1]+row.getHeight()/2f){insertion=i;break;}}if(marked!=null)marked.setForeground(null);if(rows.isEmpty())return;bottom=insertion==rows.size();marked=rows.get(bottom?rows.size()-1:insertion);marker.bottom=bottom;marked.setForeground(marker);marker.invalidateSelf();}
 public void cancel(){handler.removeCallbacks(ticker);if(marked!=null)marked.setForeground(null);if(source!=null){source.setAlpha(1);source.getParent().requestDisallowInterceptTouchEvent(false);}source=marked=null;}
 private final class Marker extends Drawable {private final Paint ink=new Paint(3);boolean bottom;public void draw(Canvas c){ink.setColor(0xffa675ff);float y=bottom?getBounds().bottom-2*density:0;c.drawRect(0,y,getBounds().right,y+2*density,ink);}public void setAlpha(int a){}public void setColorFilter(ColorFilter filter){}public int getOpacity(){return PixelFormat.TRANSLUCENT;}}
}
